class Solution {
    public int countConsistentStrings(String allowed, String[] words) {
        boolean[] allowedTable = new boolean[26];
        for (int i = 0; i < allowed.length(); i++) {
            allowedTable[allowed.charAt(i) - 'a'] = true;
        }

        int count = 0;
        for (String word : words) {
            boolean consistent = true;
            for (int i = 0; i < word.length(); i++) {
                if (!allowedTable[word.charAt(i) - 'a']) {
                    consistent = false;
                    break;
                }
            }
            if (consistent) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int countConsistentStrings(String allowed, String[] words) {
        int allowedMask = 0;
        for (int i = 0; i < allowed.length(); i++) {
            allowedMask |= 1 << (allowed.charAt(i) - 'a');
        }

        int count = 0;
        for (String word : words) {
            int wordMask = 0;
            for (int i = 0; i < word.length(); i++) {
                wordMask |= 1 << (word.charAt(i) - 'a');
            }
            if ((wordMask & ~allowedMask) == 0) {
                count++;
            }
        }
        return count;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int countConsistentStrings(String allowed, String[] words) {
        Set<Character> allowedSet = new HashSet<>();
        for (int i = 0; i < allowed.length(); i++) {
            allowedSet.add(allowed.charAt(i));
        }

        int count = 0;
        for (String word : words) {
            boolean consistent = true;
            for (int i = 0; i < word.length(); i++) {
                if (!allowedSet.contains(word.charAt(i))) {
                    consistent = false;
                    break;
                }
            }
            if (consistent) {
                count++;
            }
        }
        return count;
    }
}
